DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''decipher_preserved_language'' OR ')); END $$;
CREATE TABLE cmd_linguistics_decipher_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),actor_id bigint NOT NULL REFERENCES actor_actor(actor_id),language_id bigint REFERENCES camp_language(language_id),specimen_reference text NOT NULL CHECK(btrim(specimen_reference)<>''),specimen_medium text NOT NULL CHECK(specimen_medium IN('inscription','recorded-message','other')),task_command_id bigint NOT NULL UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint NOT NULL,effect smallint NOT NULL,general_meaning_recovered boolean NOT NULL);
CREATE TRIGGER cmd_linguistics_decipher_immutable BEFORE UPDATE OR DELETE ON cmd_linguistics_decipher_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_actor_language_mutation();
